function renderExpenses(){if(!has('EXPENSES_VIEW','VIEW'))return showView('dashboard');const rows=(S.data.expenses||[]).map(e=>`<tr><td>${e.expense_date}</td><td>${esc(e.expense_group)}</td><td>${esc(e.category)}</td><td>${e.request_type==='ADVANCE_REQUEST'?'Advance request':'Expense'}</td><td class="money">${money(e.amount)}</td><td>${esc(e.status)}</td></tr>`);const act=has('EXPENSES_CREATE','CREATE')?'<button class="btn primary" id="expenseBtn">＋ Add</button>':'';$('#view').innerHTML=pageHead('Expenses','Accounting manages company expenses. Lead/Associate may submit their own permitted advance/allowance requests. Admin does not manage or track expenses.',act)+`<section class="panel">${table(['Date','Group','Category','Type','Amount','Status'],rows)}</section>`;$('#expenseBtn')?.addEventListener('click',openExpense)}
