function renderFiles(){const rows=(S.data.files||[]).filter(f=>!f.deleted_at).map(f=>`<tr><td>${esc(f.file_name)}</td><td>${esc(f.record_type||'Project file')}</td><td>${new Date(f.created_at).toLocaleString()}</td><td><button class="btn small" data-file="${esc(f.storage_path)}" data-name="${esc(f.file_name)}">Download</button></td></tr>`);const act=has('FILES_UPLOAD','UPLOAD')||has('FILES_CREATE','CREATE')?'<button class="btn primary" id="fileBtn">＋ Upload</button>':'';$('#view').innerHTML=pageHead('Files','Private Supabase Storage with scoped metadata, sharing and version support.',act)+`<section class="panel">${table(['File','Context','Uploaded','Action'],rows)}</section>`;$('#fileBtn')?.addEventListener('click',uploadFile);$$('[data-file]').forEach(b=>b.addEventListener('click',async()=>{try{const blob=await OfficeDB.download(b.dataset.file);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=b.dataset.name||'download';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){toast(errorMessage(e),'error')}}))}
function uploadFile(){const input=document.createElement('input');input.type='file';input.accept='*/*';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{setBusy(true);if(file.size>25*1024*1024)throw new Error('Maximum file size is 25 MB.');const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`files/${S.ctx.profile.user_id}/${crypto.randomUUID()}-${safe}`;await OfficeDB.upload(file,path);try{await OfficeDB.insert('files',{uploaded_by:S.ctx.profile.user_id,storage_path:path,file_name:file.name,mime_type:file.type||'application/octet-stream',size_bytes:file.size,bucket:OfficeDB.BUCKET,extension:(file.name.split('.').pop()||'').toLowerCase(),visibility:'CONTEXT',version:1})}catch(e){try{await OfficeDB.removeFile(path)}catch{}throw e}toast('File uploaded.');await refresh()}catch(e){toast(errorMessage(e),'error')}finally{setBusy(false)}};input.click()}
async function renderChat(){if(!has('CHAT_VIEW','VIEW')&&!OfficePermissions.isAdmin())return showView('dashboard');if(S.chatUnsub){S.chatUnsub();S.chatUnsub=null}const uid=S.ctx.profile.user_id;const conversations=await OfficeDB.list('direct_conversations',{order:'last_message_at'});const visible=conversations.filter(c=>c.user_one===uid||c.user_two===uid);const others=(S.data.profiles||[]).filter(p=>p.user_id!==uid&&p.is_active);const rows=visible.map(c=>{const oid=c.user_one===uid?c.user_two:c.user_one;const other=others.find(p=>p.user_id===oid)||(S.data.profiles||[]).find(p=>p.user_id===oid);return `<button class="chat-row" data-chat="${c.id}" data-other="${oid}"><span class="avatar">${esc((other?.display_name||'?').slice(0,1).toUpperCase())}</span><span><strong>${esc(other?.display_name||'Private chat')}</strong><small>${c.last_message_at?new Date(c.last_message_at).toLocaleString():'No messages yet'}</small></span></button>`}).join('');$('#view').innerHTML=pageHead('Chat','Private one-to-one communication. Database RLS restricts conversations and messages to participants.',`<button class="btn primary" id="newChat">＋ New private chat</button>`)+`<section class="chat-shell panel"><aside class="chat-list">${rows||'<div class="empty-state"><strong>No private chats yet</strong><span>Start a conversation with an authorized employee.</span></div>'}</aside><section class="chat-panel" id="chatPanel"><div class="chat-placeholder"><strong>Select a conversation</strong><span>Only the two participants can access these messages.</span></div></section></section>`;$('#newChat').onclick=()=>openNewChat(others);$$('[data-chat]').forEach(b=>b.onclick=()=>openConversation(b.dataset.chat,b.dataset.other));S.chatUnsub=OfficeDB.subscribe('direct_messages','INSERT',payload=>{if(S.view==='chat'&&S.activeChat&&payload.new?.conversation_id===S.activeChat)openConversation(S.activeChat,S.activeOther)} )}
async function openNewChat(others){const fields=[{name:'other',label:'Employee',type:'select',required:true,options:others.map(x=>[x.user_id,x.display_name])}];openDialog('New private chat',fields,async v=>{const a=S.ctx.profile.user_id,b=v.other;const userOne=a<b?a:b,userTwo=a<b?b:a;const existing=(await OfficeDB.list('direct_conversations')).find(c=>c.user_one===userOne&&c.user_two===userTwo);if(existing){await openConversation(existing.id,b);return}await OfficeDB.insert('direct_conversations',{user_one:userOne,user_two:userTwo});await renderChat()})}
async function openConversation(cid,otherId){const uid=S.ctx.profile.user_id;S.activeChat=cid;S.activeOther=otherId;const msgs=await OfficeDB.list('direct_messages',{eq:{conversation_id:cid},order:'sent_at',ascending:true});const other=(S.data.profiles||[]).find(p=>p.user_id===otherId);$('#chatPanel').innerHTML=`<div class="chat-head"><div class="avatar">${esc((other?.display_name||'?').slice(0,1).toUpperCase())}</div><div><strong>${esc(other?.display_name||'Private chat')}</strong><small>Participant-only access</small></div></div><div class="chat-messages" id="chatMessages">${msgs.map(m=>`<div class="chat-bubble ${m.sender_id===uid?'mine':''}"><div>${esc(m.deleted_at?'Message deleted':m.body)}</div><small>${new Date(m.sent_at).toLocaleString()}${m.read_at?' · Read':''}</small></div>`).join('')||'<div class="empty-state">No messages yet.</div>'}</div><form id="chatComposer" class="chat-composer"><textarea name="body" maxlength="5000" placeholder="Write a private message…"></textarea><input name="attachment" type="file" aria-label="Attach private file"><button class="btn primary" type="submit">Send</button></form>`;$('#chatComposer').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),body=String(fd.get('body')||'').trim(),file=e.currentTarget.attachment.files?.[0];if(!body&&!file)return;try{setBusy(true);const msg=await OfficeDB.insert('direct_messages',{conversation_id:cid,sender_id:uid,body:body||'Attachment'});if(file){if(file.size>25*1024*1024)throw new Error('Maximum attachment size is 25 MB.');const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=`direct/${cid}/${crypto.randomUUID()}-${safe}`;await OfficeDB.upload(file,path);try{await OfficeDB.insert('direct_message_attachments',{message_id:msg.id,uploaded_by:uid,storage_path:path,file_name:file.name,mime_type:file.type||'application/octet-stream',size_bytes:file.size})}catch(e){try{await OfficeDB.removeFile(path)}catch{}throw e}};e.currentTarget.reset();await openConversation(cid,otherId)}catch(e){toast(errorMessage(e),'error')}finally{setBusy(false)}};$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight}
